impl NodeEndpoint {
    /// Writes the struct's fields at `version` as a JSON object.
    pub(crate) fn write_json_fields(&self, json: &mut crate::JsonWriter, _version: i16) {
        json.begin_object();
        json.key("nodeId").integer(i64::from(self.node_id));
        json.key("host").string(&self.host);
        json.key("port").integer(i64::from(self.port));
        json.key("rack").nullable(self.rack.as_deref(), |json, value| {
            json.string(value);
        });
        json.end_object();
    }
}

impl NodeEndpoint {
    fn write_fields(
        &self,
        writer: &mut crate::Writer,
        _version: i16,
    ) -> Result<(), crate::EncodeError> {
        writer.write_i32(self.node_id);
        writer.write_string(crate::Framing::Compact, &self.host)?;
        writer.write_i32(self.port);
        writer.write_nullable_string(crate::Framing::Compact, self.rack.as_deref())?;
        let mut raw = crate::RawTaggedFieldWriter::new(&self.unknown_tagged_fields)?;
        writer.write_tagged_field_count(raw.len())?;
        raw.write_rest(writer)?;
        Ok(())
    }
}

